ssh yyf@10.2.32.14 "python3 - <<'PY'
from pathlib import Path
keys = ['IMAGE_AGENT_ELASTICSEARCH_URL', 'IMAGE_AGENT_ELASTICSEARCH_INDEX', 'IMAGE_AGENT_ELASTICSEARCH_API_KEY', 'IMAGE_AGENT_RAG_EMBEDDING_PROVIDER', 'IMAGE_AGENT_RAG_EMBEDDING_MODEL', 'IMAGE_AGENT_RAG_EMBEDDING_BASE_URL', 'IMAGE_AGENT_RAG_EMBEDDING_API_KEY']
env = Path('/home/yyf/project/image_agent/.env')
seen = {}
if env.exists():
    for raw in env.read_text(errors='replace').splitlines():
        line = raw.strip()
        if not line or line.startswith('#') or '=' not in line:
            continue
        key, value = line.split('=', 1)
        if key in keys:
            seen[key] = bool(value.strip())
for key in keys:
    print(f'{key}=' + ('set' if seen.get(key) else 'missing'))
print('secret_values_not_printed=true')
PY"
